"use client";
import type { CSSProperties } from "react";
import { ButtonSurface, buttonVariables, type AnimationButtonProps } from "./button-shared";

export interface BackgroundFillButtonProps extends AnimationButtonProps {
  startScale?: number;
  hoverScale?: number;
  exitDirection?: "top" | "bottom";
}
const css = `
.z-anb-background{overflow:hidden;transition:transform var(--z-anb-duration) var(--z-anb-easing),color var(--z-anb-duration) var(--z-anb-easing)}
.z-anb-background-fill{border-radius:inherit;transform:translateY(101%) scale(var(--z-anb-start-scale,.5));transition:transform var(--z-anb-duration) var(--z-anb-easing)}
.z-anb-background[data-active=true]{transform:scale(var(--z-anb-hover-scale,.95))}.z-anb-background[data-active=true] .z-anb-background-fill{transform:translateY(0) scale(1)}
.z-anb-background[data-exit=top][data-active=false] .z-anb-background-fill{transform:translateY(-101%) scale(var(--z-anb-start-scale,.5))}
@media(prefers-reduced-motion:reduce){.z-anb-background[data-active=true]{transform:none}}
`;
/** A rounded fill rises from below while the button subtly compresses. */
export function BackgroundFillButton({
  children = "Contact Us",
  startScale = 0.5,
  hoverScale = 0.95,
  exitDirection = "bottom",
  ...props
}: BackgroundFillButtonProps) {
  return (
    <>
      <style>{css}</style>
      <ButtonSurface
        {...props}
        variant="background"
        variables={
          {
            ...buttonVariables(props),
            "--z-anb-start-scale": Math.max(0, startScale),
            "--z-anb-hover-scale": Math.max(0.1, hoverScale),
          } as CSSProperties
        }
        onEngage={(element) => element.removeAttribute("data-exit")}
        onDisengage={(element) => element.setAttribute("data-exit", exitDirection)}
        onTransitionEnd={(event) => {
          props.onTransitionEnd?.(event);
          const element = event.currentTarget,
            fill = event.target as HTMLElement;
          if (
            event.propertyName !== "transform" ||
            !fill.classList.contains("z-anb-background-fill") ||
            element.dataset.active !== "false" ||
            element.dataset.exit !== "top"
          )
            return;
          // Reset the offscreen seed after a completed upward exit. A new
          // interaction still enters from below; interrupted motion reverses.
          fill.style.transition = "none";
          element.removeAttribute("data-exit");
          void fill.offsetHeight;
          fill.style.removeProperty("transition");
        }}
      >
        <span className="z-anb-fill z-anb-background-fill" aria-hidden="true" />
        <span className="z-anb-label">{children}</span>
      </ButtonSurface>
    </>
  );
}
